css:
.prose-chapter {
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  min-width: 0;
  padding: clamp(30px, 7.5%, 64px) clamp(22px, 5.4%, 46px) clamp(34px, 7.6%, 65px) clamp(22px, 7.5%, 64px);
  background: transparent;
  border: 0;
  border-radius: 0;
  color: var(--reader-ink);
}
.prose-chapter::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: 0;
  pointer-events: none;
  --stamp-hole: clamp(7px, 2.82cqi, 20.5px);
  --stamp-corner: clamp(9px, 3.58cqi, 26px);
  --stamp-side: clamp(8px, 3.1cqi, 22.5px);
  background: #f7f6f3 url('data:image/svg+xml;base64,') repeat;
  background-size: 220px 220px;
  -webkit-mask-image: radial-gradient(circle at 8.20% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 8.20% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 15.80% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 15.80% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 23.40% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 23.40% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 31.00% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 31.00% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 38.60% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 38.60% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 46.20% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 46.20% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 53.80% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 53.80% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 61.40% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 61.40% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 69.00% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 69.00% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 76.60% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 76.60% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 84.20% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 84.20% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 91.80% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 91.80% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 0% 0%, transparent var(--stamp-corner), #000 calc(var(--stamp-corner) + .6px)),
    radial-gradient(circle at 0% 100%, transparent var(--stamp-corner), #000 calc(var(--stamp-corner) + .6px)),
    radial-gradient(circle at 0% 26%, transparent var(--stamp-side), #000 calc(var(--stamp-side) + .6px)),
    radial-gradient(circle at 100% 0%, transparent var(--stamp-corner), #000 calc(var(--stamp-corner) + .6px)),
    radial-gradient(circle at 100% 100%, transparent var(--stamp-corner), #000 calc(var(--stamp-corner) + .6px)),
    radial-gradient(circle at 100% 26%, transparent var(--stamp-side), #000 calc(var(--stamp-side) + .6px));
  mask-image: radial-gradient(circle at 8.20% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 8.20% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 15.80% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 15.80% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 23.40% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 23.40% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 31.00% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 31.00% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 38.60% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 38.60% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 46.20% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 46.20% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 53.80% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 53.80% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 61.40% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 61.40% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 69.00% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 69.00% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 76.60% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 76.60% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 84.20% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 84.20% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 91.80% 0%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 91.80% 100%, transparent var(--stamp-hole), #000 calc(var(--stamp-hole) + .6px)),
    radial-gradient(circle at 0% 0%, transparent var(--stamp-corner), #000 calc(var(--stamp-corner) + .6px)),
    radial-gradient(circle at 0% 100%, transparent var(--stamp-corner), #000 calc(var(--stamp-corner) + .6px)),
    radial-gradient(circle at 0% 26%, transparent var(--stamp-side), #000 calc(var(--stamp-side) + .6px)),
    radial-gradient(circle at 100% 0%, transparent var(--stamp-corner), #000 calc(var(--stamp-corner) + .6px)),
    radial-gradient(circle at 100% 100%, transparent var(--stamp-corner), #000 calc(var(--stamp-corner) + .6px)),
    radial-gradient(circle at 100% 26%, transparent var(--stamp-side), #000 calc(var(--stamp-side) + .6px));
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-composite: source-in;
  mask-composite: intersect;
}
.paragraph {
  position: relative;
  font-size: var(--reader-size);
  line-height: 1.8;
  font-weight: 400;
  letter-spacing: -.012em;
  text-indent: 0;
  text-align: justify;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  margin: 0 0 1.25em;
}
.paragraph:last-of-type { margin-bottom: 0; }
.paragraph q, .paragraph .prose-quote { color: var(--reader-ink); background: #EEEEEE; border-radius: 3px; padding: .08em .18em; box-decoration-break: clone; -webkit-box-decoration-break: clone; text-decoration: none; }
.paragraph strong { color: #111110; font-weight: 700; }
.paragraph em { color: #242421; font-style: italic; }
.paragraph del { color: #292926; text-decoration: line-through; text-decoration-thickness: .055em; }
.paragraph code { color: #363632; background: #77777712; padding: .08em .25em; border-radius: 2px; font-size: .86em; }
.prose-title { position: relative; margin: 0 0 1em; padding: 0 0 .55em; font-family: inherit; font-size: 28px; line-height: 1.45; font-weight: 600; text-align: left; color: var(--reader-ink); letter-spacing: .03em; }
.prose-title::after { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 1px; background: repeating-linear-gradient(to right, #999993 0 8px, transparent 8px 13px); }
@container (max-width: 400px) {
  .paragraph { font-size: 17px; line-height: 1.8; letter-spacing: .01em; margin-bottom: 1.2em; }
  .prose-title { font-size: 26px; }
}
